38	  const { tab } = await searchParams;
39	
40	  const [all, plans, users] = await Promise.all([
41	    getAllSettings(),
42	    db.plan.findMany({ orderBy: { sortOrder: "asc" }, select: { slug: true, name: true } }),
43	    db.user.findMany({
44	      orderBy: [{ role: "asc" }, { createdAt: "asc" }],
45	      select: { id: true, name: true, email: true, role: true, createdAt: true, suspended: true },
46	    }),
47	  ]);
48	
