859	export async function adminGrantFreeVps(prev: any, formData: FormData): Promise<{ error?: string }> {
860	  const admin = await requireAdmin();
861	  const parsed = z
862	    .object({
863	      userId: z.string().min(1),
864	      planId: z.string().min(1),
865	      osTemplateId: z.string().min(1),
866	      hostname: z.string().min(3).max(40).regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i),
867	    })
868	    .safeParse({
869	      userId: formData.get("userId"),
870	      planId: formData.get("planId"),
871	      osTemplateId: formData.get("osTemplateId"),
872	      hostname: formData.get("hostname"),
873	    });
874	  if (!parsed.success) return { error: "Invalid input (hostname: letters/digits/hyphens, 3-40 chars)." };
875	
876	  const target = await db.user.findUnique({ where: { id: parsed.data.userId } });
877	  if (!target) return { error: "User not found." };
878	
879	  const server = await db.server.create({
880	    data: {
881	      name: parsed.data.hostname,
882	      hostname: parsed.data.hostname,
883	      userId: target.id,
884	      planId: parsed.data.planId,
885	      osTemplateId: parsed.data.osTemplateId,
886	      isFree: true,
887	      // Gifted outright: nothing was charged, so nothing may prorate out. (A free
888	      // server has a null `expiresAt` and prorates to zero anyway, but this row can
889	      // later be given an expiry by adminSetServerFree/adminExtendServer, and the
890	      // rate basis must already be honest when that happens.)
891	      termPromoPercent: 100,
892	    },
893	  });
894	  await db.job.create({ data: { type: "PROVISION", serverId: server.id } });
895	  await audit(admin.id, "admin.grant_free_vps", `user=${target.email} server=${server.id}`);
896	  redirect(`/admin/servers`);
897	}
