899	export async function adminSuspendServer(serverId: string, suspend: boolean) {
900	  const admin = await requireAdmin();
901	  // Record WHY. An admin suspension is NOT an unpaid one: the renewal sweep skips
902	  // suspended servers, so a paid-up customer suspended here is never charged and
903	  // never warned — and before `suspendReason` existed, `terminateOverdue` then
904	  // deleted their VM and all its data once the untouched term lapsed. Tagging it
905	  // ADMIN keeps the terminator away from it and stops "Renew now" silently
906	  // reversing an administrative decision.
907	  await db.server.update({
908	    where: { id: serverId },
909	    data: suspend
910	      ? { suspendReason: "ADMIN", suspendedNote: "suspended by support — contact us to restore access" }
911	      : { suspendReason: null, suspendedNote: null },
912	  });
913	  await db.job.create({ data: { type: suspend ? "SUSPEND" : "UNSUSPEND", serverId } });
914	  await audit(admin.id, suspend ? "admin.suspend_server" : "admin.unsuspend_server", serverId);
915	  revalidatePath("/admin/servers");
916	}
