15	export default async function AdminAnalytics() {
16	  await requireArea("analytics");
17	
18	  const now = new Date();
19	  const since30d = new Date(Date.now() - 30 * 86400_000);
20	  const sixMonthsAgo = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 5, 1));
21	  const twelveWeeksAgo = new Date(Date.now() - 12 * 7 * 86400_000);
22	
23	  const [charges6mo, signups, activeServers, deletions30d, spend30d, firstUser] = await Promise.all([
24	    db.walletTransaction.findMany({
25	      where: { amountCents: { lt: 0 }, createdAt: { gte: sixMonthsAgo } },
26	      select: { amountCents: true, createdAt: true },
27	    }),
28	    db.user.findMany({
29	      where: { createdAt: { gte: twelveWeeksAgo } },
30	      select: { createdAt: true },
31	    }),
32	    db.server.findMany({
33	      where: { status: { notIn: ["DELETING"] } },
34	      include: { plan: { select: { id: true, name: true, priceCents: true } }, user: { select: { id: true, email: true, name: true } } },
35	    }),
36	    db.auditLog.count({ where: { action: "server.delete", createdAt: { gte: since30d } } }),
37	    db.walletTransaction.aggregate({
38	      where: { amountCents: { lt: 0 }, createdAt: { gte: since30d } },
39	      _sum: { amountCents: true },
40	    }),
41	    db.user.findFirst({ orderBy: { createdAt: "asc" }, select: { createdAt: true } }),
42	  ]);
43	
44	  // Revenue by month (last 6 calendar months)
45	  const monthKeys: string[] = [];
46	  const revByMonth = new Map<string, number>();
47	  for (let i = 5; i >= 0; i--) {
48	    const k = monthKey(new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - i, 1)));
49	    monthKeys.push(k);
50	    revByMonth.set(k, 0);
51	  }
52	  for (const tx of charges6mo) {
53	    const k = monthKey(tx.createdAt);
54	    if (revByMonth.has(k)) revByMonth.set(k, (revByMonth.get(k) ?? 0) + Math.abs(tx.amountCents));
55	  }
56	  const revSeries = monthKeys.map((k) => (revByMonth.get(k) ?? 0) / 100);
57	
58	  // Signups by week (last 12 weeks)
59	  const weekBuckets = Array.from({ length: 12 }, () => 0);
60	  for (const u of signups) {
61	    const weeksAgo = Math.floor((Date.now() - u.createdAt.getTime()) / (7 * 86400_000));
62	    if (weeksAgo >= 0 && weeksAgo < 12) weekBuckets[11 - weeksAgo]++;
63	  }
64	
65	  // Plan distribution
66	  const byPlan = new Map<string, { name: string; count: number }>();
67	  for (const s of activeServers) {
68	    const cur = byPlan.get(s.plan.id) ?? { name: s.plan.name, count: 0 };
69	    cur.count++;
70	    byPlan.set(s.plan.id, cur);
71	  }
72	  const planEntries = [...byPlan.values()].sort((a, b) => b.count - a.count);
73	
74	  // ARPU
75	  const revenue30dCents = -(spend30d._sum.amountCents ?? 0);
76	  const activeCustomers = new Set(activeServers.map((s) => s.user.id)).size;
77	  const arpuCents = activeCustomers > 0 ? Math.round(revenue30dCents / activeCustomers) : 0;
78	
79	  // Top customers by committed monthly spend (active paid servers)
80	  const byCustomer = new Map<string, { email: string; name: string; mrrCents: number; servers: number }>();
81	  for (const s of activeServers) {
82	    const cur = byCustomer.get(s.user.id) ?? { email: s.user.email, name: s.user.name, mrrCents: 0, servers: 0 };
83	    cur.servers++;
84	    if (!s.isFree) cur.mrrCents += s.plan.priceCents;
85	    byCustomer.set(s.user.id, cur);
86	  }
87	  const topCustomers = [...byCustomer.entries()]
88	    .sort((a, b) => b[1].mrrCents - a[1].mrrCents)
89	    .slice(0, 8);
90	
91	  const platformAgeDays = firstUser ? Math.floor((Date.now() - firstUser.createdAt.getTime()) / 86400_000) : 0;
92	  const shortHistory = platformAgeDays < 30;
93	
94	  return (
95	    <div className="space-y-6">
96	      <PageHeader
97	        title="Business analytics"
98	        sub={
99	          shortHistory
100	            ? `All figures since launch (${platformAgeDays}d of history) — trends firm up as data accrues.`
101	            : "Revenue, growth and customer metrics from live platform data."
102	        }
103	      />
104	
105	      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
106	        <StatCard label="Revenue · last 30d" value={fmtMoney(revenue30dCents)} delta={shortHistory ? "since launch" : "trailing 30 days"} />
107	        <StatCard
108	          label="ARPU · 30d"
109	          value={fmtMoney(arpuCents)}
110	          delta={`across ${activeCustomers} active customer${activeCustomers === 1 ? "" : "s"}`}
