64	  const spamPct = stats.rspamd.sampled
65	    ? Math.round((stats.rspamd.spam / stats.rspamd.sampled) * 100)
66	    : 0;
67	
68	  const rspamdActions = Object.entries(stats.rspamd.actions).sort((a, b) => b[1] - a[1]);
69	
70	  return (
71	    <div className="space-y-6">
72	      <div className="flex flex-wrap items-center justify-between gap-2">
