6	/**
7	 * Admin deliverability stats fetch. Platform-area gated. Returns a discriminated
8	 * result so the UI can distinguish "not configured" from "unreachable" from live
9	 * data — it never throws out to the caller.
10	 */
11	export type MailStatsResult =
12	  | { state: "unconfigured" }
13	  | { state: "unreachable"; message: string }
14	  | { state: "ok"; stats: MailStats };
15	
16	export async function refreshMailStats(): Promise<MailStatsResult> {
17	  await requireArea("platform");
18	  if (!mailcowConfigured()) return { state: "unconfigured" };
19	  try {
20	    const stats = await mcStats();
21	    return { state: "ok", stats };
22	  } catch (e) {
23	    return { state: "unreachable", message: e instanceof Error ? e.message : String(e) };
24	  }
25	}
