1	import { db } from "@/lib/db";
2	
3	/**
4	 * Plain (non-action) aggregation helpers for the visitor-analytics admin page.
5	 * These are read-only Prisma queries over the `Visit` table. Everything is
6	 * scoped to short recent windows and small `take` limits so the page stays
7	 * cheap even as the visit log grows.
8	 */
9	
10	const DAY = 86_400_000;
11	
12	/** Distinct client IPs seen in the last `minutes` — our "live visitors now" gauge. */
13	export async function liveVisitors(minutes = 5): Promise<number> {
14	  const since = new Date(Date.now() - minutes * 60_000);
15	  const rows = await db.visit.findMany({
16	    where: { createdAt: { gte: since } },
17	    distinct: ["ip"],
18	    select: { ip: true },
19	  });
20	  return rows.length;
21	}
22	
23	/** Total page views since local midnight. */
24	export async function todayViews(): Promise<number> {
25	  const start = new Date();
26	  start.setHours(0, 0, 0, 0);
27	  return db.visit.count({ where: { createdAt: { gte: start } } });
28	}
29	
30	/** Total page views in the trailing `days` window (default 7d). */
31	export async function viewsInWindow(days = 7): Promise<number> {
32	  const since = new Date(Date.now() - days * DAY);
33	  return db.visit.count({ where: { createdAt: { gte: since } } });
34	}
35	
36	/** Distinct visitors (by IP) in the trailing `days` window. */
37	export async function uniqueVisitors(days = 7): Promise<number> {
38	  const since = new Date(Date.now() - days * DAY);
39	  const rows = await db.visit.findMany({
40	    where: { createdAt: { gte: since } },
41	    distinct: ["ip"],
42	    select: { ip: true },
43	  });
44	  return rows.length;
45	}
46	
47	/** Reduce a raw referrer URL to a bare hostname for grouping/display. */
48	export function referrerHost(ref: string | null | undefined): string | null {
49	  if (!ref) return null;
50	  try {
51	    const h = new URL(ref).hostname.replace(/^www\./, "");
52	    return h || null;
53	  } catch {
54	    const trimmed = ref.trim();
55	    return trimmed ? trimmed.slice(0, 60) : null;
56	  }
57	}
58	
59	export type Counted = { label: string; count: number };
60	
61	/** Top external referrer hosts over the trailing `days` window. */
62	export async function topReferrers(days = 7, limit = 8): Promise<Counted[]> {
63	  const since = new Date(Date.now() - days * DAY);
64	  const rows = await db.visit.findMany({
65	    where: { createdAt: { gte: since }, referrer: { not: null } },
66	    select: { referrer: true },
67	    take: 5000,
68	    orderBy: { createdAt: "desc" },
69	  });
70	  const tally = new Map<string, number>();
71	  for (const r of rows) {
72	    const host = referrerHost(r.referrer);
73	    if (!host) continue;
74	    tally.set(host, (tally.get(host) ?? 0) + 1);
75	  }
76	  return [...tally.entries()]
77	    .map(([label, count]) => ({ label, count }))
78	    .sort((a, b) => b.count - a.count)
79	    .slice(0, limit);
80	}
81	
82	/** Top countries among geocoded visits over the trailing `days` window. */
83	export async function topCountries(days = 30, limit = 8): Promise<Counted[]> {
84	  const since = new Date(Date.now() - days * DAY);
85	  const grp = await db.visit.groupBy({
86	    by: ["country"],
87	    where: { createdAt: { gte: since }, geocoded: true, country: { not: null } },
88	    _count: { _all: true },
89	  });
90	  return grp
91	    .map((g) => ({ label: g.country as string, count: g._count._all }))
92	    .sort((a, b) => b.count - a.count)
93	    .slice(0, limit);
94	}
95	
96	/** Top cities among geocoded visits over the trailing `days` window. */
97	export async function topCities(days = 30, limit = 8): Promise<Counted[]> {
98	  const since = new Date(Date.now() - days * DAY);
99	  const rows = await db.visit.findMany({
100	    where: { createdAt: { gte: since }, geocoded: true, city: { not: null } },
101	    select: { city: true, country: true },
102	    take: 5000,
103	    orderBy: { createdAt: "desc" },
104	  });
105	  const tally = new Map<string, number>();
106	  for (const r of rows) {
107	    const label = r.country ? `${r.city}, ${r.country}` : (r.city as string);
108	    tally.set(label, (tally.get(label) ?? 0) + 1);
109	  }
110	  return [...tally.entries()]
111	    .map(([label, count]) => ({ label, count }))
112	    .sort((a, b) => b.count - a.count)
113	    .slice(0, limit);
114	}
